package cu.hogarplaya;
import org.json.*;import java.util.*;
public class SharedCartClearTest {
 static int n;static void ok(boolean b){if(!b)throw new AssertionError();n++;}
 static JSONObject empty()throws Exception{return new JSONObject("{products:[],offers:[],shared:[],queue:[],conflicts:[]}");}
 static JSONObject row(int i,boolean bought)throws Exception{return new JSONObject().put("id",new UUID(0,i+1).toString()).put("name","Producto "+i).put("quantity",1).put("unit","lb").put("bought",bought).put("deleted",false).put("revision",2);}
 static JSONArray ids(JSONObject v)throws Exception{JSONArray a=new JSONArray();for(int i=0;i<v.getJSONArray("shared").length();i++)a.put(v.getJSONArray("shared").getJSONObject(i).getString("id"));return a;}
 public static void main(String[] args)throws Exception {
  JSONObject source=empty();source.put("sentinelFinancial",new JSONObject("{amount:450,uuid:'unchanged'}"));for(int i=0;i<3;i++)source.getJSONArray("shared").put(row(i,i==2));String before=source.toString();JSONObject cleared=SharedCartClear.plan(source,ids(source),"p");ok(source.toString().equals(before));ok(cleared.getJSONArray("queue").length()==3);ok(cleared.getJSONObject("sharedIntents").length()==3);ok(cleared.getJSONObject("sentinelFinancial").getInt("amount")==450);
  for(int i=0;i<3;i++)ok(cleared.getJSONArray("queue").getJSONObject(i).getJSONObject("item").getBoolean("deleted"));String ops=cleared.getJSONArray("queue").toString();JSONObject retry=SharedCartClear.plan(cleared,ids(source),"p");ok(retry.getJSONArray("queue").toString().equals(ops));ok(retry.getJSONObject("sharedIntents").length()==3);
  JSONObject pending=empty(),one=row(7,false);one.remove("revision");JSONArray cart=new JSONArray().put(new JSONObject("{id:'cart-line',name:'Papa',quantity:2,unitCode:'lb'}"));pending=SharedCartLive.noteShare(SharedCartPlan.plan(pending,cart,"p","device","home"),cart,"p","device","home");JSONObject q=pending.getJSONArray("queue").getJSONObject(0);JSONArray own=new JSONArray().put(q.getString("entityId"));String immutable=q.toString();JSONObject removed=SharedCartClear.plan(pending,own,"p");ok(removed.getJSONArray("queue").getJSONObject(0).toString().equals(immutable));ok(removed.getJSONObject("sharedIntents").getJSONObject(own.getString(0)).getJSONObject("item").getBoolean("deleted"));ok(removed.getJSONObject("sharedCartOwners").length()==0);ok(removed.getJSONObject("cartShares").length()==0);ok(!removed.getJSONObject("sharedCartActive").optBoolean("p"));
  ok(SharedCartLive.migrate(removed,cart,"p","device","home").getJSONObject("sharedCartOwners").length()==0);ok(SharedCartLive.changedCart(removed,cart,new JSONObject(),"p","cart","device","home").getJSONArray("queue").length()==1);
  JSONObject conflict=empty();JSONObject r=row(9,false);conflict.getJSONArray("shared").put(r);JSONObject op=new JSONObject().put("id",UUID.randomUUID().toString()).put("entityId",r.getString("id")).put("item",r);conflict.getJSONArray("conflicts").put(new JSONObject().put("local",op).put("remote",r));JSONObject resolved=SharedCartClear.plan(conflict,ids(conflict),"p");ok(resolved.getJSONArray("conflicts").length()==0);ok(resolved.getJSONArray("queue").getJSONObject(0).getInt("baseRevision")==2);ok(resolved.getJSONArray("queue").getJSONObject(0).getJSONObject("item").getBoolean("deleted"));
  JSONObject many=empty();for(int i=0;i<500;i++)many.getJSONArray("shared").put(row(i,false));JSONObject bulk=SharedCartClear.plan(many,ids(many),"p");ok(bulk.getJSONArray("queue").length()==100);ok(bulk.getJSONObject("sharedIntents").length()==500);ok(many.getJSONArray("queue").length()==0);
  JSONObject remote=SharedCartLive.noteShare(SharedCartPlan.plan(empty(),cart,"p","device","home"),cart,"p","device","home");JSONObject bound=remote.getJSONArray("queue").getJSONObject(0).getJSONObject("item");remote.put("queue",new JSONArray()).put("shared",new JSONArray().put(new JSONObject(bound.toString()).put("revision",1).put("deleted",true)));JSONObject received=SharedCartClear.received(remote);ok(received.getJSONObject("sharedCartOwners").length()==0);ok(received.getJSONObject("cartShares").length()==0);ok(!received.getJSONObject("sharedCartActive").optBoolean("p"));
  JSONObject again=SharedCartPlan.plan(received,cart,"p","device","home");ok(!again.getJSONArray("queue").getJSONObject(0).getJSONObject("item").getBoolean("deleted"));ok(again.getJSONArray("queue").getJSONObject(0).getInt("baseRevision")==1);
  JSONArray unknown=new JSONArray().put(UUID.randomUUID().toString());ok(SharedCartClear.plan(source,unknown,"p").getJSONArray("queue").length()==0);try{SharedCartClear.plan(source,new JSONArray().put("invalid"),"p");throw new AssertionError();}catch(IllegalArgumentException expected){n++;}ok(source.toString().equals(before));
  System.out.println("PASS: "+n+" clear checks; todos los estados/filtros, cola inmutable, retirada por lotes, reintentos, referencias desactivadas y datos originales conservados.");
 }
}
